"""The iDrive customization catalog shipped in the app (generated by
tools/make_idrive_tweaks.py)."""

import json
import os
import sys
import unittest

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
sys.path.insert(0, os.path.join(ROOT, "tools"))

import make_idrive_tweaks as lib  # noqa: E402

JSON_PATH = os.path.join(ROOT, "ios-app", "BMWLinkKit", "Sources", "BMWLinkKit", "Resources",
                         "idrive-tweaks.json")


class IDriveTweaksTests(unittest.TestCase):
    def setUp(self):
        with open(JSON_PATH, encoding="utf-8") as f:
            self.text = f.read()
        self.data = json.loads(self.text)
        self.tweaks = self.data["tweaks"]

    def test_committed_json_is_up_to_date(self):
        self.assertEqual(self.text, lib.render(), "run: python3 tools/make_idrive_tweaks.py")

    def test_unique_ids_and_known_fields(self):
        ids = [t["id"] for t in self.tweaks]
        self.assertEqual(len(ids), len(set(ids)))
        for t in self.tweaks:
            self.assertIn(t["category"], self.data["categories"])
            self.assertIn(t["risk"], ("green", "amber"))
            self.assertIn(t["moduleAddress"], (0x63, 0x60, 0x40))
            for key in ("title", "what", "why", "how", "undo", "module"):
                self.assertTrue(t[key].strip(), f"{t['id']} empty {key}")
            # BMW Link never writes coding: every "how" points at BimmerCode.
            self.assertIn("BimmerCode", t["how"])

    def test_amber_tweaks_have_a_caveat(self):
        for t in self.tweaks:
            if t["risk"] == "amber":
                self.assertTrue(t["caveat"], f"{t['id']} amber but no caveat")

    def test_sport_displays_present(self):
        ids = {t["id"] for t in self.tweaks}
        self.assertIn("sport-displays", ids)
        self.assertIn("carplay-fullscreen", ids)

    def test_no_engine_or_safety_modules(self):
        # Stays in infotainment/comfort: never the engine computer or safety modules.
        for t in self.tweaks:
            self.assertNotIn(t["moduleAddress"], (0x12, 0x01, 0x29, 0x30),
                             f"{t['id']} touches an engine/safety module")


if __name__ == "__main__":
    unittest.main()
